using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;

namespace DungeonContract.Editor
{
    public static class DcP1Checks
    {
        private static JObject parameters;
        private static JObject geometry;
        private static long serial;
        private static readonly List<string> passed=new List<string>();
        private static DcP1World Create(string kit="ranger",bool practice=true)
        {
            return new DcP1World(new JObject { ["parameters"]=parameters,["p1_world"]=geometry,["practice"]=practice,["seed"]=20261012,["mode"]="normal",["run_id"]="p1_check",["members"]=new JArray(new JObject { ["player_id"]="1",["slot"]=0,["loadout_id"]=kit }) });
        }
        private static JToken Player(DcP1World world)=>world.Snapshot()["players"][0];
        private static DcP1Input Input(uint sequence=1)=>new DcP1Input {Sequence=sequence,Aim=0,Placement=new Vector2(4,5),HasPlacement=true};
        private static void Step(DcP1World world,long time,DcP1Input? input=null)
        {
            world.AdvanceTime(time);world.Input("1",input??Input((uint)++serial));world.Tick(time);
        }
        private static void Action(DcP1World world,string action,long time,DcP1Input? input=null)
        {
            world.AdvanceTime(time);var intent=input??Input((uint)++serial);world.Input("1",intent);world.QueueAction("1",action,intent,"check_"+(++serial));world.Tick(time);
        }
        private static void Assert(bool condition,string message){if(!condition)throw new InvalidOperationException(message);}
        private static void Case(string name,System.Action check){check();passed.Add(name);}
        public static void Run()
        {
            parameters=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/contracts/planned-v3/parameters.json")));geometry=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/world-v3-p1.json")));passed.Clear();
            Case("D2-004_short_click_and_normalized_move",()=>{var world=Create();Action(world,"ranged_press",33);Assert((int)Player(world)["magazine"]==7,"Short click disappeared");var diagonal=Input(20);diagonal.Move=Vector2.one;Step(world,66,diagonal);var own=Player(world);Assert(Vector2.Distance(new Vector2((float)own["x"],(float)own["y"]),new Vector2(3,5))<=0.168f,"Diagonal speed exceeded normal");});
            Case("D2-005_light_heavy_exclusive",()=>{var world=Create();Action(world,"melee_begin",33);Action(world,"melee_release",100);Assert((long)Player(world)["light_attacks"]==1&&(long)Player(world)["heavy_attacks"]==0,"Light double attack");Action(world,"melee_release",133);Assert((long)Player(world)["light_attacks"]==1,"Second release attacked");Action(world,"melee_begin",500);Action(world,"melee_release",1500);Assert((long)Player(world)["heavy_attacks"]==1,"Heavy absent");});
            Case("D2-006_charge_cancels_without_release",()=>{var world=Create();Action(world,"melee_begin",33);var input=Input(100);input.Move=Vector2.right;input.Attack=true;Step(world,66,input);Assert((int)Player(world)["magazine"]==8&&Math.Abs((float)Player(world)["x"]-3.116667f)<0.01f,"Charge movement/attack conflict");Action(world,"cancel_input",100);Assert(!(bool)Player(world)["charging"]&&(long)Player(world)["heavy_attacks"]==0,"Canceled charge fired");});
            Case("D2-007_charge_dodge_locks_direction",()=>{var world=Create();Action(world,"melee_begin",33);var input=Input(50);input.Move=Vector2.right;Action(world,"dodge",66,input);input.Move=Vector2.up;input.Attack=true;Step(world,99,input);Assert((float)Player(world)["dodge_direction_x"]>0.99f&&(float)Player(world)["dodge_direction_y"]==0&&(bool)Player(world)["charging"],"Dodge turned/canceled charge");});
            Case("D2-008_first_dodge_and_wall",()=>{var world=Create();var intent=Input(50);intent.Aim=16384;Action(world,"dodge",33,intent);Assert((float)Player(world)["dodge_direction_y"]>0.99f,"First dodge did not use aim");for(var index=2;index<20;index++)Step(world,index*33);Assert((float)Player(world)["y"]<=8.7f,"Dodge crossed wall");});
            Case("D2-009_magazine_reload_interrupt",()=>{var world=Create();for(var index=0;index<8;index++)Action(world,"ranged_press",33+index*200);Assert((int)Player(world)["magazine"]==0,"Magazine incorrect");Action(world,"reload",1700);Assert((long)Player(world)["reload_remaining_ms"]==900,"Reload absent");Action(world,"ability_secondary",1733,new DcP1Input {Sequence=500,Aim=0,Placement=new Vector2(-10,-10),HasPlacement=true});Assert((long)Player(world)["reload_remaining_ms"]>0,"Failed skill canceled reload");Action(world,"dodge",1766);Assert((int)Player(world)["magazine"]==0&&(long)Player(world)["reload_remaining_ms"]==0,"Interrupted reload granted ammo");var rune=Create("runesmith");Action(rune,"reload",33);Assert(rune.LastActionReason=="not_reloadable","Runesmith reloaded");});
            Case("D2-010_two_independent_actives",()=>{var world=Create();Action(world,"ability_primary",33);Assert((int)Player(world)["magazine"]==8&&(long)Player(world)["ability_remaining_ms"]==8000,"Volleys consumed ammo");Action(world,"ability_secondary",66);Assert((long)Player(world)["secondary_remaining_ms"]==12000&&((JArray)world.Snapshot()["fields"]).Count==1,"Second skill absent");});
            Case("D2-011_twin_atomic_and_cooldown",()=>{var world=Create("runesmith");world.InstallForCheck("1","runesmith_twin");Action(world,"ability_primary",33);Assert(((JArray)world.Snapshot()["turrets"]).Count==2,"Twin turret not deployed together");var bad=Input(100);bad.Placement=new Vector2(1,1);var fresh=Create("runesmith");fresh.InstallForCheck("1","runesmith_twin");Action(fresh,"ability_primary",33,bad);Assert(((JArray)fresh.Snapshot()["turrets"]).Count==0&&(long)Player(fresh)["ability_remaining_ms"]==0,"Invalid twin partially deployed");});
            Case("D2-012_shared_arc_geometry",()=>{Assert(DcP1World.InArc(Vector2.zero,new Vector2(1,0),Vector2.right,1.2f,90),"Inside arc rejected");Assert(!DcP1World.InArc(Vector2.zero,new Vector2(0,1),Vector2.right,1.2f,90),"Outside arc hit");Assert(!DcP1World.InArc(Vector2.zero,new Vector2(2,0),Vector2.right,1.2f,90),"Outside radius hit");});
            Case("D2-013_independent_enemy_state",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["players"][0]["Room"]=1;checkpoint["players"][0]["Position"]=new JObject { ["x"]=3,["y"]=5 };world.Restore(checkpoint);for(var index=1;index<=100;index++)Step(world,index*33);var snapshot=world.Snapshot();Assert(((JArray)snapshot["enemies"]).Count>1,"Enemy room did not start");Assert(((JArray)snapshot["enemies"]).All(enemy=>enemy["warning"]!=null),"Enemy FSM missing");});
            Case("D2-014_lock_room_exit",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["rooms"][1]["Status"]="active";checkpoint["players"][0]["Room"]=1;checkpoint["players"][0]["Position"]=new JObject { ["x"]=1.4f,["y"]=5 };world.Restore(checkpoint);var input=Input(100);input.Move=Vector2.left;Step(world,33,input);Assert((int)Player(world)["room_id"]==1,"Player escaped active room");});
            Case("D2-015_mechanism_and_enemies_independent",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["rooms"][2]["Status"]="active";checkpoint["rooms"][2]["Wave"]=3;checkpoint["players"][0]["Room"]=2;checkpoint["players"][0]["Position"]=new JObject { ["x"]=11,["y"]=5 };world.Restore(checkpoint);Step(world,33);Assert((string)world.Snapshot()["rooms"][2]["status"]=="active","Empty unfinished mechanism room cleared");var input=Input(500);input.Interact=true;for(var index=2;index<130;index++)Step(world,index*33,input);Assert((bool)world.Snapshot()["rooms"][2]["mechanism_complete"]&&(string)world.Snapshot()["rooms"][2]["status"]=="cleared","Legal completed mechanism did not clear");});
            Case("D2-016_trap_environment_attribution",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["rooms"][2]["Status"]="active";checkpoint["rooms"][2]["Wave"]=3;var enemy=(JObject)checkpoint["enemies"].FirstOrDefault();if(enemy==null){enemy=new JObject { ["ID"]="trap_test",["Kind"]="guard",["Room"]=2,["Position"]=new JObject{["x"]=7,["y"]=5},["Health"]=20,["Maximum"]=20,["AttackAt"]=999999 };((JArray)checkpoint["enemies"]).Add(enemy);}world.Restore(checkpoint);for(var index=1;index<28;index++)Step(world,index*33);Assert((long)Player(world)["damage"]==0&&(int)Player(world)["deaths"]==0,"Environment invented player stats");});
            Case("D2-017_cover_destroyed_next_frame",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["players"][0]["Room"]=1;checkpoint["players"][0]["Position"]=new JObject { ["x"]=5,["y"]=6 };world.Restore(checkpoint);Action(world,"melee_begin",33);Action(world,"melee_release",1000);Assert((int)world.Snapshot()["covers"][0]["health"]==0&&(int)world.Snapshot()["covers"][0]["revision"]==1,"Cover destruction not committed");Assert((long)Player(world)["damage"]==0,"Cover counted as enemy damage");});
            Case("D2-018_safe_spawn_and_pending_queue",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["players"][0]["Room"]=1;checkpoint["players"][0]["Position"]=new JObject { ["x"]=3,["y"]=5 };world.Restore(checkpoint);for(var index=1;index<100;index++)Step(world,index*33);var snapshot=world.Snapshot();Assert(((JArray)snapshot["enemies"]).Count<=8,"Room live cap exceeded");Assert((int)snapshot["rooms"][1]["pending"]>0,"Pending wave vanished");});
            Case("InputSystem_action_maps_and_bindings",()=>{using var controls=new DcP1Controls();Assert(controls.Asset.actionMaps.Count==6,"Missing action contexts");Assert(controls.Asset.FindActionMap("Gameplay").FindAction("Melee").bindings.Count==1,"Melee binding missing");});
            Case("D2-017_projectile_never_pierces_breaking_cover",()=>{var world=Create();var checkpoint=world.Capture();checkpoint["players"][0]["Room"]=1;checkpoint["players"][0]["Position"]=new JObject{["x"]=5,["y"]=6};var enemy=checkpoint["enemies"][0];enemy["Room"]=1;enemy["Position"]=new JObject{["x"]=7,["y"]=6};world.Restore(checkpoint);for(var shot=0;shot<4;shot++){Action(world,"ranged_press",33+shot*200);for(var frame=1;frame<5;frame++)Step(world,33+shot*200+frame*33);}Assert((int)world.Snapshot()["covers"][0]["health"]==0&&(long)Player(world)["damage"]==0,"Breaking projectile pierced cover");Action(world,"ranged_press",1000);for(var frame=1;frame<8;frame++)Step(world,1000+frame*33);Assert((long)Player(world)["damage"]>0,"Destroyed cover continued blocking");});
            Case("D2-012_enemy_attack_damages_cover_and_keeps_warning",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["players"][0]["Room"]=1;checkpoint["players"][0]["Position"]=new JObject{["x"]=4,["y"]=6};((JArray)checkpoint["enemies"]).Add(new JObject{["ID"]="guard_test",["Kind"]="guard",["Room"]=1,["Position"]=new JObject{["x"]=7,["y"]=6},["Origin"]=new JObject{["x"]=7,["y"]=6},["Aim"]=new JObject{["x"]=-1,["y"]=0},["Warning"]="melee",["WarningUntil"]=33,["Health"]=80,["Maximum"]=80,["AttackAt"]=99999});world.Restore(checkpoint);Step(world,33);Assert((int)world.Snapshot()["covers"][0]["health"]<30,"Enemy did not damage cover");Assert((int)Player(world)["health"]==100,"Enemy struck through cover");});
            Case("D2-014_late_entry_and_boss_warning",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["rooms"][1]["Status"]="active";checkpoint["players"][0]["Position"]=new JObject{["x"]=16.6f,["y"]=5};world.Restore(checkpoint);var input=Input(1000);input.Move=Vector2.right;Step(world,33,input);Assert((int)Player(world)["room_id"]==1,"Late legal entry blocked");checkpoint=world.Capture();for(var index=0;index<5;index++)checkpoint["rooms"][index]["Status"]="cleared";checkpoint["players"][0]["Room"]=4;checkpoint["players"][0]["DoorAt"]=0;checkpoint["players"][0]["Position"]=new JObject{["x"]=16.6f,["y"]=5};world.Restore(checkpoint);Step(world,66,input);Assert((int)Player(world)["room_id"]==5&&(long)world.Snapshot()["boss_warning_remaining_ms"]==3000,"Boss warning incorrect");});
            Case("D2-015_early_mechanism_does_not_skip_enemies",()=>{var world=Create(practice:false);var checkpoint=world.Capture();checkpoint["rooms"][2]["Status"]="active";checkpoint["rooms"][2]["Wave"]=3;checkpoint["rooms"][2]["Mechanism"]=true;((JArray)checkpoint["enemies"]).Add(new JObject{["ID"]="remaining_guard",["Kind"]="guard",["Room"]=2,["Position"]=new JObject{["x"]=6,["y"]=3},["Health"]=80,["Maximum"]=80,["AttackAt"]=99999});world.Restore(checkpoint);Step(world,33);Assert((string)world.Snapshot()["rooms"][2]["status"]=="active","Mechanism skipped remaining enemy");});
            Case("P1_six_room_terminal_and_zero_contracts",()=>{var world=Create(practice:false);var checkpoint=world.Capture();for(var index=0;index<5;index++){checkpoint["rooms"][index]["Status"]="cleared";checkpoint["rooms"][index]["Mechanism"]=true;}checkpoint["rooms"][5]["Status"]="active";checkpoint["rooms"][5]["Wave"]=1;world.Restore(checkpoint);Step(world,33);Assert(world.Outcome=="success"&&((JArray)world.Snapshot()["completed"]).All(value=>(bool)value),"P1 completed room graph did not end");});
            Case("D2-008_dodge_passes_normal_blocks_boss",()=>{foreach(var kind in new[]{"guard","elite","boss"}){var world=Create();var checkpoint=world.Capture();var enemy=checkpoint["enemies"][0];enemy["Kind"]=kind;enemy["Position"]=new JObject{["x"]=4,["y"]=5};checkpoint["enemies"][1]["Position"]=new JObject{["x"]=13,["y"]=7};world.Restore(checkpoint);var input=Input(2000);input.Move=Vector2.right;input.Attack=true;Action(world,"dodge",33,input);for(var frame=2;frame<=7;frame++)Step(world,frame*33,input);Assert(kind=="guard"?(float)Player(world)["x"]>4.4f:(float)Player(world)["x"]<3.6f,"Dodge collision incorrect for "+kind);Assert((int)Player(world)["magazine"]<8,"Dodge stopped held fire");}});
            Case("D2-018_spawn_failure_bounded_without_kills",()=>{var blocked=(JObject)geometry.DeepClone();blocked["rooms"][1]["obstacles_milli"]=new JArray { new JArray(1000,1000,16000,8000) };var world=new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=blocked,["practice"]=false,["seed"]=1,["mode"]="normal",["members"]=new JArray(new JObject{["player_id"]="1",["slot"]=0,["loadout_id"]="ranger"})});var checkpoint=world.Capture();checkpoint["rooms"][1]["Status"]="active";checkpoint["rooms"][1]["Wave"]=1;checkpoint["rooms"][1]["Pending"]=new JArray("guard");world.Restore(checkpoint);for(var frame=1;frame<600&&!world.Terminal;frame++)Step(world,frame*33);Assert(world.Outcome=="aborted"&&(long)world.Snapshot()["elapsed_ms"]<20000&&(int)Player(world)["deaths"]==0,"Unbounded/forged spawn recovery");});
            var output=DcBootstrap.Argument("-dc-p1-check-output");if(string.IsNullOrEmpty(output))throw new InvalidOperationException("P1 evidence path required");Directory.CreateDirectory(Path.GetDirectoryName(output));File.WriteAllText(output,new JObject { ["kind"]="v3_p1_authoritative_simulation",["passed_groups"]=passed.Count,["cases"]=new JArray(passed),["human_playtests"]=0,["real_udp"]=false,["gameplay_rewards"]=false }.ToString());Debug.Log("DC v3 P1 checks passed: "+passed.Count);
        }
    }
}
